        // Grid Blocks Generator (GeoJSON Mocks)
        function generateBlockGrid(center, count = 20) {
            let features = [];
            let latBase = center[0];
            let lngBase = center[1];
            
            for (let i = 0; i < count; i++) {
                let row = Math.floor(i / 5);
                let col = i % 5;
                
                // Block size approx 100m x 100m (roughly 0.0009 degrees)
                let size = 0.0012;
                let latMin = latBase + (row * size) - 0.003;
                let latMax = latMin + size;
                let lngMin = lngBase + (col * size) - 0.003;
                let lngMax = lngMin + size;
                
                let blockId = 20 + i;
                features.push({
                    "type": "Feature",
                    "properties": {
                        "name": `Block ${blockId}`,
                        "n": parseFloat((2.0 + Math.random() * 1.1).toFixed(2)),
                        "p": parseFloat((0.10 + Math.random() * 0.10).toFixed(3)),
                        "k": parseFloat((0.60 + Math.random() * 0.85).toFixed(2)),
                        "mg": parseFloat((0.15 + Math.random() * 0.15).toFixed(2))
                    },
                    "geometry": {
                        "type": "Polygon",
                        "coordinates": [[
                            [lngMin, latMin],
                            [lngMax, latMin],
                            [lngMax, latMax],
                            [lngMin, latMax],
                            [lngMin, latMin]
                        ]]
                    }
                });
            }
            return { "type": "FeatureCollection", "features": features };
        }

        // Reusable leaflet layer color styling matching python helper
        function getNutrientColorComp(val, type) {
            if (type === "N") {
                if (val <= 2.1) return "#ff0000";
                if (val <= 2.3) return "#ff9900";
                if (val <= 2.5) return "#ffff00";
                if (val <= 2.7) return "#00dc00";
                if (val <= 2.9) return "#0066ff";
                return "#995522";
            } else if (type === "P") {
                if (val <= 0.120) return "#ff0000";
                if (val <= 0.135) return "#ff9900";
                if (val <= 0.150) return "#ffff00";
                if (val <= 0.165) return "#00dc00";
                if (val <= 0.180) return "#0066ff";
                return "#995522";
            } else if (type === "K") {
                if (val <= 0.70) return "#ff0000";
                if (val <= 0.85) return "#ff9900";
                if (val <= 1.00) return "#ffff00";
                if (val <= 1.15) return "#00dc00";
                if (val <= 1.30) return "#0066ff";
                return "#995522";
            } else if (type === "Mg") {
                if (val <= 0.20) return "#ff0000";
                if (val <= 0.22) return "#ff9900";
                if (val <= 0.24) return "#ffff00";
                if (val <= 0.26) return "#00dc00";
                if (val <= 0.28) return "#0066ff";
                return "#995522";
            }
            return "transparent";
        }

        // Sample authentic raster values from pixel grids or compute spatial fallback
        function sampleRastersOrFallback(lat, lng) {
            let result = {
                n: null,
                p: null,
                k: null,
                mg: null
            };

            for (let key of ["N", "P", "K", "Mg"]) {
                if (typeof RASTER_GRID_DATA !== 'undefined' && RASTER_GRID_DATA[key]) {
                    let r = RASTER_GRID_DATA[key];
                    let wgs_left = r.bounds.left;
                    let wgs_bottom = r.bounds.bottom;
                    let wgs_right = r.bounds.right;
                    let wgs_top = r.bounds.top;

                    if (lat >= wgs_bottom && lat <= wgs_top && lng >= wgs_left && lng <= wgs_right) {
                        let col = Math.floor(((lng - wgs_left) / (wgs_right - wgs_left)) * r.width);
                        let row = Math.floor(((wgs_top - lat) / (wgs_top - wgs_bottom)) * r.height);
                        
                        if (row >= 0 && row < r.height && col >= 0 && col < r.width) {
                            let val = r.data[row][col];
                            if (val !== -9999) {
                                result[key.toLowerCase()] = val;
                            }
                        }
                    }
                }
            }

            // Fallback to spatial algorithm if outside rasters or nodata found
            if (result.n === null) result.n = parseFloat((2.45 + (lat * 100) % 0.4).toFixed(2));
            if (result.p === null) result.p = parseFloat((0.14 + (lng * 100) % 0.05).toFixed(3));
            if (result.k === null) result.k = parseFloat((1.05 + (lat * 50) % 0.3).toFixed(2));
            if (result.mg === null) result.mg = parseFloat((0.25 + (lng * 50) % 0.1).toFixed(3));

            return result;
        }

        // Initialize maps
        window.addEventListener('DOMContentLoaded', () => {
            if (typeof L === 'undefined') {
                console.warn('Leaflet library not loaded yet or offline.');
                return;
            }
            // Leaflet map (Page 2)
            mapComp = L.map('map-comprehensive-element', { zoomControl: true }).setView(lahadDatuCoords, 15);
            L.tileLayer('https://mt1.google.com/vt/lyrs=y&x={x}&y={y}&z={z}', {
                maxZoom: 20,
                subdomains: ['mt0', 'mt1', 'mt2', 'mt3'],
                attribution: '&copy; Google Maps'
            }).addTo(mapComp);
            mapComp.on('click', (e) => {
                handleMapDirectClick(e.latlng, 'comp');
            });

            // Leaflet map (Page 3)
            mapStd = L.map('map-standard-element', { zoomControl: true }).setView(lahadDatuCoords, 15);
            L.tileLayer('https://mt1.google.com/vt/lyrs=y&x={x}&y={y}&z={z}', {
                maxZoom: 20,
                subdomains: ['mt0', 'mt1', 'mt2', 'mt3'],
                attribution: '&copy; Google Maps'
            }).addTo(mapStd);
            mapStd.on('click', (e) => {
                handleMapDirectClick(e.latlng, 'std');
            });

            // Load initial shape boundaries
            loadShapeBoundaries('lahad_datu');
        });

        // Trigger loading shape data on both maps
        function loadShapeBoundaries(type) {
            let blocksData = REAL_MAPS_DATA[type];
            if (!blocksData) return;
            
            let center = (type === 'lahad_datu') ? lahadDatuCoords : serayaCoords;
            let mapName = blocksData.mapName || ((type === 'lahad_datu') ? 'Lahad Datu with block boundary' : 'Seraya with block boundary');
            
            // Clean old layers
            if (compBoundaryLayer) mapComp.removeLayer(compBoundaryLayer);
            if (stdBoundaryLayer) mapStd.removeLayer(stdBoundaryLayer);
            if (compRasterOverlay) {
                mapComp.removeLayer(compRasterOverlay);
                compRasterOverlay = null;
            }
            if (stdRasterOverlay) {
                mapStd.removeLayer(stdRasterOverlay);
                stdRasterOverlay = null;
            }
            
            // Reset radio controls and legends
            let offRadioComp = document.querySelector('input[name="comp_layer"][value="OFF"]');
            if (offRadioComp) offRadioComp.checked = true;
            document.querySelectorAll('#page-comprehensive .nutrient-legend-box').forEach(el => el.style.display = 'none');

            let offRadioStd = document.querySelector('input[name="std_layer"][value="OFF"]');
            if (offRadioStd) offRadioStd.checked = true;
            document.querySelectorAll('#page-standard .nutrient-legend-box').forEach(el => el.style.display = 'none');
            
            // Render on Page 2 map
            compBoundaryLayer = L.geoJSON(blocksData, {
                style: { color: "#ff7800", weight: 2, fillOpacity: 0.15, fillColor: "#ff7800" },
                onEachFeature: (feature, layer) => {
                    layer.bindTooltip(feature.properties.name, { sticky: true, className: 'block-tooltip' });
                    layer.on('click', (e) => {
                        L.DomEvent.stopPropagation(e);
                        handleBlockClick(feature, e.latlng, 'comp');
                    });
                }
            }).addTo(mapComp);
            
            // Render on Page 3 map
            stdBoundaryLayer = L.geoJSON(blocksData, {
                style: { color: "#12b886", weight: 2, fillOpacity: 0.15, fillColor: "#12b886" },
                onEachFeature: (feature, layer) => {
                    layer.bindTooltip(feature.properties.name, { sticky: true });
                    layer.on('click', (e) => {
                        L.DomEvent.stopPropagation(e);
                        handleBlockClick(feature, e.latlng, 'std');
                    });
                }
            }).addTo(mapStd);

            if (compBoundaryLayer && compBoundaryLayer.getBounds().isValid()) {
                try {
                    mapComp.fitBounds(compBoundaryLayer.getBounds(), { padding: [30, 30] });
                    mapStd.fitBounds(stdBoundaryLayer.getBounds(), { padding: [30, 30] });
                } catch(e) {}
            } else {
                mapComp.panTo(center);
                mapStd.panTo(center);
            }

            // Clean clicked markers
            if (clickedMarkerComp) {
                mapComp.removeLayer(clickedMarkerComp);
                clickedMarkerComp = null;
            }
            if (clickedMarkerStd) {
                mapStd.removeLayer(clickedMarkerStd);
                clickedMarkerStd = null;
            }

            // Set coordinates and zone text matching PyQt selection change exactly
            document.getElementById('comp-coords').innerText = "Coordinates: Click anywhere inside boundaries";
            document.getElementById('comp-zone').innerText = `Zone: Map boundary (${mapName}) loaded`;
            document.getElementById('std-coords').innerText = "Coordinates: Click anywhere inside boundaries";
            document.getElementById('std-zone').innerText = `Zone: Map boundary (${mapName}) loaded`;

            // Reset card values to "-- %" until a block is clicked!
            document.getElementById('comp-n-val').innerText = "-- %";
            document.getElementById('comp-p-val').innerText = "-- %";
            document.getElementById('comp-k-val').innerText = "-- %";
            document.getElementById('comp-mg-val').innerText = "-- %";

            document.getElementById('std-n-val').innerText = "-- %";
            document.getElementById('std-p-val').innerText = "-- %";
            document.getElementById('std-k-val').innerText = "-- %";
            document.getElementById('std-mg-val').innerText = "-- %";
        }

        // =========================================================================
        // REAL SHAPEFILE (.SHP / .ZIP / .DBF) UPLOAD & PARSING SYSTEM
        // =========================================================================
        async function handleShapefileUpload(event) {
            const files = event.target.files;
            if (!files || files.length === 0) return;

            try {
                let geojson = null;
                let fileName = "";
                let fileList = Array.from(files);

                let zipFile = fileList.find(f => f.name.toLowerCase().endsWith('.zip'));
                let shpFile = fileList.find(f => f.name.toLowerCase().endsWith('.shp'));
                let dbfFile = fileList.find(f => f.name.toLowerCase().endsWith('.dbf'));
                let prjFile = fileList.find(f => f.name.toLowerCase().endsWith('.prj'));

                if (zipFile) {
                    fileName = zipFile.name;
                    const buffer = await zipFile.arrayBuffer();
                    if (window.shp) {
                        let parsed = await shp(buffer);
                        geojson = Array.isArray(parsed) ? parsed[0] : parsed;
                    } else {
                        throw new Error("Shapefile parser library is still loading. Please try again in a moment.");
                    }
                } else if (shpFile) {
                    fileName = shpFile.name;
                    const shpBuffer = await shpFile.arrayBuffer();
                    let dbfBuffer = dbfFile ? await dbfFile.arrayBuffer() : null;
                    let prjText = prjFile ? await prjFile.text() : null;

                    if (window.shp) {
                        let geometries = shp.parseShp(shpBuffer, prjText);
                        let properties = dbfBuffer ? shp.parseDbf(dbfBuffer) : [];
                        geojson = shp.combine([geometries, properties]);
                    } else {
                        throw new Error("Shapefile parser library is still loading. Please try again in a moment.");
                    }
                } else {
                    alert("Please select a .shp file (with optional .dbf and .prj) or a .zip file containing shapefile components.");
                    return;
                }

                if (!geojson || !geojson.features || geojson.features.length === 0) {
                    throw new Error("No valid shapefile features found in the selected file(s).");
                }

                let prjText = prjFile ? await prjFile.text() : null;
                geojson = reprojectGeoJSONIfNeeded(geojson, prjText);

                // Assign feature block names
                geojson.features.forEach((feature, idx) => {
                    if (!feature.properties) feature.properties = {};
                    let props = feature.properties;
                    let foundName = props.name || props.NAME || props.Name || props.BLOCK || props.Block || props.block || props.ID || props.Id || props.id || props.LABEL || props.Label;
                    feature.properties.name = foundName ? String(foundName) : (`Block ${idx + 1}`);
                });

                let customKey = 'custom_' + Date.now();
                let mapDisplayName = `Custom: ${fileName} (${geojson.features.length} blocks)`;
                geojson.mapName = mapDisplayName;
                REAL_MAPS_DATA[customKey] = geojson;

                // Update select dropdowns
                ['map-select-comp', 'map-select-std'].forEach(selectId => {
                    let select = document.getElementById(selectId);
                    if (select) {
                        let opt = document.createElement('option');
                        opt.value = customKey;
                        opt.innerText = mapDisplayName;
                        opt.selected = true;
                        select.appendChild(opt);
                    }
                });

                // Load newly created shapefile
                onMapSelectChanged(customKey);

                alert(`Shapefile '${fileName}' loaded successfully!\n${geojson.features.length} block boundaries displayed on the map.`);
            } catch (err) {
                console.error("Shapefile Upload Error:", err);
                alert("Failed to parse Shapefile: " + err.message);
            } finally {
                event.target.value = "";
            }
        }

        function reprojectGeoJSONIfNeeded(geojson, prjText) {
            if (!geojson || !geojson.features || geojson.features.length === 0) return geojson;

            let firstFeat = geojson.features[0];
            let sampleCoord = null;
            if (firstFeat.geometry) {
                if (firstFeat.geometry.type === 'Point') {
                    sampleCoord = firstFeat.geometry.coordinates;
                } else if (firstFeat.geometry.type === 'Polygon') {
                    sampleCoord = firstFeat.geometry.coordinates[0][0];
                } else if (firstFeat.geometry.type === 'MultiPolygon') {
                    sampleCoord = firstFeat.geometry.coordinates[0][0][0];
                }
            }

            if (!sampleCoord) return geojson;

            let x = sampleCoord[0];
            let y = sampleCoord[1];

            // If coordinates are in lat/lng (-180..180, -90..90), no reprojection needed
            if (Math.abs(x) <= 180 && Math.abs(y) <= 90) return geojson;

            let sourceProj = null;

            if (prjText && window.proj4) {
                try {
                    proj4.defs("CUSTOM_PRJ", prjText);
                    sourceProj = "CUSTOM_PRJ";
                } catch (e) {
                    console.warn("Could not parse .prj with proj4:", e);
                }
            }

            if (!sourceProj && window.proj4) {
                // Fallback UTM Zone 50N (EPSG:32650) for Sabah
                proj4.defs("EPSG:32650", "+proj=utm +zone=50 +datum=WGS84 +units=m +no_defs");
                sourceProj = "EPSG:32650";
            }

            if (!sourceProj || !window.proj4) return geojson;

            function transformPt(pt) {
                try {
                    let res = proj4(sourceProj, "EPSG:4326", [pt[0], pt[1]]);
                    return [res[0], res[1]];
                } catch (e) {
                    return pt;
                }
            }

            function transformGeom(geom) {
                if (!geom || !geom.coordinates) return geom;
                if (geom.type === 'Point') {
                    geom.coordinates = transformPt(geom.coordinates);
                } else if (geom.type === 'LineString' || geom.type === 'MultiPoint') {
                    geom.coordinates = geom.coordinates.map(transformPt);
                } else if (geom.type === 'Polygon' || geom.type === 'MultiLineString') {
                    geom.coordinates = geom.coordinates.map(ring => ring.map(transformPt));
                } else if (geom.type === 'MultiPolygon') {
                    geom.coordinates = geom.coordinates.map(poly => poly.map(ring => ring.map(transformPt)));
                }
                return geom;
            }

            geojson.features.forEach(feat => {
                if (feat.geometry) {
                    feat.geometry = transformGeom(feat.geometry);
                }
            });

            return geojson;
        }

        // Handle Click Event on block boundaries
        function handleBlockClick(feature, latlng, page) {
            selectedBlock = feature.properties.name;
            selectedLat = latlng.lat;
            selectedLng = latlng.lng;
            
            let sampled = sampleRastersOrFallback(latlng.lat, latlng.lng);
            updateNutrientValues(sampled);
            
            // Update Coordinate Labels
            let coordStr = `Coordinates: Lat=${latlng.lat.toFixed(5)}, Lng=${latlng.lng.toFixed(5)}`;
            if (page === 'comp') {
                document.getElementById('comp-coords').innerText = coordStr;
                document.getElementById('comp-zone').innerText = `Zone: Map boundary (${selectedBlock} with block boundary) loaded`;
                
                // Add marker
                if (clickedMarkerComp) mapComp.removeLayer(clickedMarkerComp);
                clickedMarkerComp = L.marker(latlng).addTo(mapComp).bindPopup(`<b>${selectedBlock}</b>`).openPopup();
            } else {
                document.getElementById('std-coords').innerText = coordStr;
                document.getElementById('std-zone').innerText = `Zone: Map boundary (${selectedBlock} with block boundary) loaded`;
                
                if (clickedMarkerStd) mapStd.removeLayer(clickedMarkerStd);
                clickedMarkerStd = L.marker(latlng).addTo(mapStd).bindPopup(`<b>${selectedBlock}</b>`).openPopup();
            }
        }

        // Handle Direct Map Click Events (Outside Boundaries)
        function handleMapDirectClick(latlng, page) {
            selectedBlock = "Block 22";
            selectedLat = latlng.lat;
            selectedLng = latlng.lng;
            
            let sampled = sampleRastersOrFallback(latlng.lat, latlng.lng);
            updateNutrientValues(sampled);
            
            // Update Coordinate Labels
            let coordStr = `Coordinates: Lat=${latlng.lat.toFixed(5)}, Lng=${latlng.lng.toFixed(5)}`;
            if (page === 'comp') {
                document.getElementById('comp-coords').innerText = coordStr;
                document.getElementById('comp-zone').innerText = `Zone: Oil Palm Plantation (Outside Boundary)`;
                
                // Add marker
                if (clickedMarkerComp) mapComp.removeLayer(clickedMarkerComp);
                clickedMarkerComp = L.marker(latlng).addTo(mapComp).bindPopup(`<b>Point Detection</b>`).openPopup();
            } else {
                document.getElementById('std-coords').innerText = coordStr;
                document.getElementById('std-zone').innerText = `Zone: Oil Palm Plantation (Outside Boundary)`;
                
                if (clickedMarkerStd) mapStd.removeLayer(clickedMarkerStd);
                clickedMarkerStd = L.marker(latlng).addTo(mapStd).bindPopup(`<b>Point Detection</b>`).openPopup();
            }
        }

        // Update values in sidebar displays
        function updateNutrientValues(props) {
            currentNutrients = {
                N: props.n,
                P: props.p,
                K: props.k,
                Mg: props.mg
            };
            
            // Comprehensive Panel
            document.getElementById('comp-n-val').innerText = `${props.n} %`;
            document.getElementById('comp-p-val').innerText = `${props.p} %`;
            document.getElementById('comp-k-val').innerText = `${props.k} %`;
            document.getElementById('comp-mg-val').innerText = `${props.mg} %`;

            // Standard Panel
            document.getElementById('std-n-val').innerText = `${props.n} %`;
            document.getElementById('std-p-val').innerText = `${props.p} %`;
            document.getElementById('std-k-val').innerText = `${props.k} %`;
            document.getElementById('std-mg-val').innerText = `${props.mg} %`;
            
            calculateStandardCorrectiveDosage();
        }

